7	/// The serialisation format for `AgentResponse::render`.
8	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
9	#[non_exhaustive]
10	pub enum OutputFormat {
11	    /// Plain-text TOON / kv format. Default.
12	    #[default]
13	    Text,
14	    /// Compact JSON object.
15	    Json,
16	}
17	
18	#[derive(Debug, Clone, PartialEq, Eq)]
19	enum RenderTarget {
20	    Unset,
21	    Toon,
22	    Kv,
23	}
24	
25	/// Default per-cell truncation limit used by [`AgentResponse::new`].
26	pub const DEFAULT_TRUNCATE_CELLS: usize = 200;
27	
28	/// Builder for an agent-facing response.
29	#[derive(Debug, Clone)]
30	#[non_exhaustive]
31	pub struct AgentResponse {
32	    /// The TOON list slot: type name, fields, rows, total count, cell cap and truncation hint, kept as the options
33	    /// the renderer validates and renders by reference, so a render never copies the rows. Its `hints` stay empty:
34	    /// the response's hints are appended after the body instead.
35	    toon: crate::toon::ToonOptions,
36	    target: RenderTarget,
37	    single_item: Vec<KvItem>,
38	    /// Sections added with [`section`](Self::section), rendered in insertion order after the `items()` / `kv_items()`
39	    /// slot (when one was set). Empty for every response that predates sections, which renders as it always did.
40	    sections: Vec<Section>,
41	    hints: Vec<Hint>,
42	    recovery: Vec<RecoveryHint>,
43	    is_error: bool,
44	    human_content: Option<String>,
45	}
46	
47	impl AgentResponse {
48	    /// Create a new, empty response for the given type name.
49	    pub fn new(type_name: impl Into<String>) -> Self {
50	        Self {
51	            toon: crate::toon::ToonOptions::new(type_name, Vec::new(), Vec::new()).max_cell_len(DEFAULT_TRUNCATE_CELLS),
52	            target: RenderTarget::Unset,
53	            single_item: Vec::new(),
54	            sections: Vec::new(),
55	            hints: Vec::new(),
56	            recovery: Vec::new(),
57	            is_error: false,
58	            human_content: None,
59	        }
60	    }
61	
62	    /// Populate the TOON list path.
63	    #[must_use]
64	    pub fn items(mut self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
65	        self.toon.rows = rows;
66	        self.toon.fields = fields.iter().map(|s| (*s).to_string()).collect();
67	        self.target = RenderTarget::Toon;
68	        self
69	    }
70	
71	    /// Set the total available count.
72	    #[must_use]
73	    pub fn total_count(mut self, n: usize) -> Self {
74	        self.toon.total_count = Some(n);
75	        self
76	    }
77	
78	    /// Report a list cut in one call: sets the total count to `outcome.total_before` and, only when something was
79	    /// cut, appends [`TruncationOutcome::hint`](crate::truncation::TruncationOutcome::hint)`(guidance)`, so the
80	    /// `totalCount` and the `help[]` line always describe the same cut.
81	    ///
82	    /// It does not set the rows: the response holds TOON [`Value`] rows, not the caller's `T`, so pass `outcome.kept`
83	    /// (converted to rows) to [`items`](Self::items) yourself. Later [`total_count`](Self::total_count) or
84	    /// [`hints`](Self::hints) calls still override what this sets.
85	    ///
86	    /// ```
87	    /// use michi_core::toon::Value;
88	    /// use michi_core::{truncate_by_count, AgentResponse, OutputFormat};
89	    ///
90	    /// let outcome = truncate_by_count(vec![1, 2, 3, 4], 2);
91	    /// let rows = outcome.kept.iter().map(|n| vec![Value::Int(*n)]).collect();
92	    /// let r = AgentResponse::new("issues").items(rows, &["n"]).truncation(&outcome, "pass --limit 4");
93	    /// assert_eq!(
94	    ///     r.render(OutputFormat::Text),
95	    ///     "issues[2]{n}:\n  1\n  2\ntotalCount: 4\nhelp[1]: showing 2 of 4; pass --limit 4"
96	    /// );
97	    /// ```
98	    #[must_use]
99	    pub fn truncation<T>(
100	        mut self,
101	        outcome: &crate::truncation::TruncationOutcome<T>,
102	        guidance: impl Into<String>,
103	    ) -> Self {
104	        self.toon.total_count = Some(outcome.total_before);
105	        if let Some(hint) = outcome.hint(guidance) {
106	            self.hints.push(hint);
107	        }
108	        self
109	    }
110	
111	    /// Populate the KV single-item path.
112	    #[must_use]
113	    pub fn kv_items(mut self, items: Vec<KvItem>) -> Self {
114	        self.single_item = items;
115	        self.target = RenderTarget::Kv;
116	        self
117	    }
118	
119	    /// Append a section. Sections render in insertion order after the `items()` / `kv_items()` slot, if one was set;
120	    /// the caller owns ordering. A response with no section, or one section and no `items()` / `kv_items()`, renders
121	    /// exactly as the sugar for that section would.
122	    ///
123	    /// The response's cell cap ([`truncate_cells_at`](Self::truncate_cells_at)) and truncation hint apply to every
124	    /// `Toon` body. A section's `totalCount` comes from [`Section::total_count`], not from the response's.
125	    #[must_use]
126	    pub fn section(mut self, section: Section) -> Self {
127	        self.sections.push(section);
128	        self
129	    }
130	
131	    /// Append a contextual hint.
132	    #[must_use]
133	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
134	        self.hints.push(Hint::new(hint));
135	        self
136	    }
137	
138	    /// Replace all contextual hints.
139	    #[must_use]
140	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
141	        self.hints = hints;
142	        self
143	    }
144	
145	    /// Append a recovery hint.
146	    #[must_use]
147	    pub fn recovery_hint(mut self, r: RecoveryHint) -> Self {
148	        self.recovery.push(r);
149	        self
150	    }
151	
152	    /// Set the max string cell length, in chars, before truncation on the TOON path. Default:
153	    /// [`DEFAULT_TRUNCATE_CELLS`].
154	    ///
155	    /// The limit counts characters before TOON escaping and quoting, so a cell that needs quotes or escapes is
156	    /// written longer than `limit` (see [`crate::toon::ToonOptions::max_cell_len`]). The KV path is never truncated.
157	    #[must_use]
158	    pub fn truncate_cells_at(mut self, limit: usize) -> Self {
159	        self.toon.max_cell_len = limit;
160	        self
161	    }
162	
163	    /// Set the caller's instruction for getting a cut TOON cell in full. When a cell was cut, michi adds one line to
164	    /// `help[]` (after your own hints) that names the `truncated` block and this instruction (see
165	    /// [`crate::toon::ToonOptions::truncation_hint`]). Unset by default: michi never invents a parameter the tool
166	    /// may not have, and the `truncated` block still reports each cut. Pass tool-author text, never data.
167	    #[must_use]
168	    pub fn truncation_hint(mut self, hint: impl Into<String>) -> Self {
169	        self.toon.truncation_hint = Some(hint.into());
170	        self
171	    }
172	
173	    /// Mark this response as an error state.
174	    #[must_use]
175	    pub fn as_error(mut self) -> Self {
176	        self.is_error = true;
177	        self
178	    }
179	
180	    /// Attach a human-facing companion block (`audience: user`).
181	    #[must_use]
182	    pub fn human_content(mut self, text: impl Into<String>) -> Self {
183	        self.human_content = Some(text.into());
184	        self
185	    }
186	
187	    /// The TOON body, and whether it is a validation-failure error block instead of the requested rows.
188	    ///
189	    /// The third item is the `help[]` line michi adds when it cut a cell and a truncation hint is set.
190	    fn toon_body(&self) -> (String, bool, Option<Hint>) {
191	        match self.toon.validate() {
192	            Ok(doc) => {
193	                let (body, extra) = doc.render_parts();
194	                (body, false, extra.map(Hint::new))
195	            }
196	            Err(e) => (validation_error_body("toon_validation_failed", &e.to_string()), true, None),
197	        }
198	    }
199	
200	    /// The caller's hints, then michi's own truncation line when there is one: a single `help` block.
201	    fn hints_with<'a>(&'a self, extra: &[Hint]) -> std::borrow::Cow<'a, [Hint]> {
202	        if extra.is_empty() {
203	            std::borrow::Cow::Borrowed(&self.hints)
204	        } else {
205	            let mut all = Vec::with_capacity(self.hints.len() + extra.len());
206	            all.extend(self.hints.iter().cloned());
207	            all.extend(extra.iter().cloned());
208	            std::borrow::Cow::Owned(all)
209	        }
210	    }
211	
212	    /// The options a `Toon` section renders by: the response's cell cap and truncation hint, the section's own
213	    /// `totalCount` rule. Copies the rows, which the single-slot path avoids by rendering its options in place.
214	    fn section_options(
215	        &self,
216	        name: &str,
217	        fields: &[String],
218	        rows: &[Vec<Value>],
219	        shown_total: Option<usize>,
220	    ) -> crate::toon::ToonOptions {
221	        let mut opts = crate::toon::ToonOptions::new(name, fields.to_vec(), rows.to_vec());
222	        opts.total_count = shown_total;
223	        opts.max_cell_len = self.toon.max_cell_len;
224	        opts.truncation_hint.clone_from(&self.toon.truncation_hint);
225	        opts
226	    }
227	
228	    /// One section's text, whether it is a validation-failure error block, and michi's truncation `help[]` line.
229	    fn section_body(&self, s: &Section) -> (String, bool, Option<Hint>) {
230	        let total = s.shown_total();
231	        match &s.body {
232	            SectionBody::Toon { fields, rows } => match self.section_options(&s.name, fields, rows, total).validate() {
233	                Ok(doc) => {
234	                    let (body, extra) = doc.render_parts();
235	                    (body, false, extra.map(Hint::new))
236	                }
237	                Err(e) => (validation_error_body("toon_validation_failed", &e.to_string()), true, None),
238	            },
239	            SectionBody::Kv(items) if items.is_empty() => {
240	                (total.map_or_else(String::new, |n| format!("totalCount: {n}")), false, None)
241	            }
242	            SectionBody::Kv(items) => match crate::kv::render_kv(items, total, &[]) {
243	                Ok(body) => (body, false, None),
244	                Err(e) => (validation_error_body("kv_validation_failed", &e.to_string()), true, None),
245	            },
246	            SectionBody::Text(text) => (text.clone(), false, None),
247	        }
248	    }
249	
250	    /// The KV body, and whether it is a validation-failure error block instead of the requested items (a duplicate
251	    /// or reserved key, see [`crate::kv::KvError`]).
252	    fn kv_body(&self) -> (String, bool) {
253	        // `render_kv` renders nothing for no items, dropping the count; a response that set one still reports it,
254	        // as the TOON path does (`t: []\ntotalCount: 0`).
255	        if self.single_item.is_empty() {
256	            let body = self.toon.total_count.map_or_else(String::new, |n| format!("totalCount: {n}"));
257	            return (body, false);
258	        }
259	        match crate::kv::render_kv(&self.single_item, self.toon.total_count, &[]) {
260	            Ok(body) => (body, false),
261	            Err(e) => (validation_error_body("kv_validation_failed", &e.to_string()), true),
262	        }
263	    }
264	
265	    /// The selected body, and whether this response is an error: set by `as_error()` or by a body that failed
266	    /// validation. Every output surface reads its error flag from here so text, JSON and MCP never disagree.
267	    fn body(&self) -> (String, bool, Vec<Hint>) {
268	        let (body, failed, extra) = match self.target {
269	            RenderTarget::Toon | RenderTarget::Unset => self.toon_body(),
270	            RenderTarget::Kv => {
271	                let (body, failed) = self.kv_body();
272	                (body, failed, None)
273	            }
274	        };
275	        let mut extras: Vec<Hint> = extra.into_iter().collect();
276	        if self.sections.is_empty() {
277	            return (body, failed || self.is_error, extras);
278	        }
279	        // With sections the legacy slot renders only when `items()` / `kv_items()` was called; an untouched response
280	        // has no body of its own to put before them. Parts are joined with one LF and empty parts are skipped.
281	        let slot_unused = self.target == RenderTarget::Unset;
282	        let mut failed = failed && !slot_unused;
283	        let mut out = if slot_unused { String::new() } else { body };
284	        if slot_unused {
285	            extras.clear();
286	        }
287	        for s in &self.sections {
288	            let (part, part_failed, part_extra) = self.section_body(s);
289	            failed |= part_failed;
290	            extras.extend(part_extra);
291	            if part.is_empty() {
292	                continue;
293	            }
294	            if !out.is_empty() {
295	                out.push('\n');
296	            }
297	            out.push_str(&part);
298	        }
299	        (out, failed || self.is_error, extras)
300	    }
301	
302	    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
303	    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
304	    /// are unique (the body cannot use `totalCount`, `help`, `recovery` or `truncated`). Appends to `body` in place.
305	    fn finish_text(&self, mut body: String, extra: &[Hint]) -> String {
306	        let hints = self.hints_with(extra);
307	        if !hints.is_empty() || !self.recovery.is_empty() {
308	            body.reserve(1 + hints.len() * 60 + self.recovery.len() * 80);
309	        }
310	        crate::hints::append_hints(&mut body, &hints);
311	        crate::recovery::append_recovery(&mut body, &self.recovery);
312	        body
313	    }
314	
315	    /// Render the response in the requested format.
316	    #[must_use]
317	    pub fn render(&self, format: OutputFormat) -> String {
318	        match format {
319	            OutputFormat::Text => self.render_text(),
320	            OutputFormat::Json => self.render_json(),
321	        }
322	    }
323	
324	    /// Render via the TOON path.
325	    #[must_use]
326	    pub fn render_toon(&self) -> String {
327	        let (body, _, extra) = self.toon_body();
328	        self.finish_text(body, extra.as_slice())
329	    }
330	
331	    /// Render via the KV path.
332	    #[must_use]
333	    pub fn render_kv(&self) -> String {
334	        self.finish_text(self.kv_body().0, &[])
335	    }
336	
337	    fn render_text(&self) -> String {
338	        let (body, _, extra) = self.body();
339	        self.finish_text(body, &extra)
340	    }
341	
342	    /// Whether this response is an error: `as_error()` was called, or the TOON rows or KV items failed validation and
343	    /// the body is a `toon_validation_failed` or `kv_validation_failed` error block. Validates without rendering.
344	    #[must_use]
345	    pub fn is_error(&self) -> bool {
346	        let slot_failed = match self.target {
347	            RenderTarget::Toon | RenderTarget::Unset => self.toon.validate().is_err(),
348	            RenderTarget::Kv => crate::kv::validate_keys(&self.single_item).is_err(),
349	        };
350	        if self.sections.is_empty() {
351	            return self.is_error || slot_failed;
352	        }
353	        self.is_error
354	            || (slot_failed && self.target != RenderTarget::Unset)
355	            || self.sections.iter().any(|s| match &s.body {
356	                SectionBody::Toon { fields, rows } => {
357	                    self.section_options(&s.name, fields, rows, s.shown_total()).validate().is_err()
358	                }
359	                SectionBody::Kv(items) => crate::kv::validate_keys(items).is_err(),
360	                SectionBody::Text(_) => false,
361	            })
362	    }
363	
364	    /// Render just the `help[N]:` block for `self.hints`.
365	    #[must_use]
366	    pub fn render_hints_only(&self) -> String {
367	        crate::hints::render_hints(&self.hints)
368	    }
369	
370	    /// Render for the given audience.
371	    #[must_use]
372	    pub fn render_for(&self, audience: crate::audience::Audience) -> String {
373	        match audience {
374	            crate::audience::Audience::Assistant => self.render_text(),
375	            crate::audience::Audience::User => self.human_content.clone().unwrap_or_else(|| self.render_text()),
376	        }
377	    }
378	
379	    /// Whether `.human_content()` was set on this builder.
380	    #[must_use]
381	    pub fn has_human_content(&self) -> bool {
382	        self.human_content.is_some()
383	    }
