385	    /// Build the MCP `CallToolResult` for this response.
386	    #[must_use]
387	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
388	        let (body, is_error, extra) = self.body();
389	        let structured_content = self.json_from_body(&body, is_error, &extra);
390	        let mut content = vec![crate::mcp::ContentBlock {
391	            text: self.finish_text(body, &extra),
392	            audience: vec![crate::audience::Audience::Assistant],
393	        }];
394	        if let Some(human) = &self.human_content {
395	            content.push(crate::mcp::ContentBlock {
396	                text: human.clone(),
397	                audience: vec![crate::audience::Audience::User],
398	            });
399	        }
400	        crate::mcp::CallToolResult { content, is_error, structured_content }
401	    }
402	
403	    fn render_json(&self) -> String {
404	        let (body, is_error, extra) = self.body();
405	        self.json_from_body(&body, is_error, &extra)
406	    }
407	
408	    fn json_from_body(&self, body: &str, is_error: bool, extra: &[Hint]) -> String {
409	        let hints = self.hints_with(extra);
410	        let capacity =
411	            body.len() + hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>() + self.recovery.len() * 64 + 64;
412	        let mut out = String::with_capacity(capacity);
413	        out.push_str("{\"body\":");
414	        json_string(&mut out, body);
415	        out.push_str(",\"hints\":[");
416	        for (i, h) in hints.iter().enumerate() {
417	            if i > 0 {
418	                out.push(',');
419	            }
420	            json_string(&mut out, h.as_str());
421	        }
422	        out.push_str("],\"recovery\":[");
423	        for (i, r) in self.recovery.iter().enumerate() {
424	            if i > 0 {
425	                out.push(',');
426	            }
427	            out.push_str("{\"tool\":");
428	            json_string(&mut out, &r.tool);
429	            out.push_str(",\"params\":");
430	            crate::recovery::push_params_json(&mut out, &r.params);
431	            if let Some(reason) = &r.reason {
432	                out.push_str(",\"reason\":");
433	                json_string(&mut out, reason);
434	            }
435	            out.push('}');
436	        }
437	        out.push_str("],\"isError\":");
438	        out.push_str(if is_error { "true" } else { "false" });
439	        out.push('}');
440	        out
441	    }
442	}
443	
444	/// The body that replaces rows or items that cannot form a valid document: `error: <code>` and the quoted message.
445	fn validation_error_body(code: &str, message: &str) -> String {
446	    let message = crate::toon::escape_value(message);
447	    let mut out = String::with_capacity(17 + code.len() + message.len());
448	    out.push_str("error: ");
449	    out.push_str(code);
450	    out.push_str("\nmessage: ");
451	    out.push_str(&message);
452	    out
453	}
454	
455	fn json_string(out: &mut String, s: &str) {
456	    crate::kv::json_escape_str(out, s);
457	}
