460	mod tests {
461	    use super::*;
462	
463	    #[test]
464	    fn capacity_violations_are_toon_validation_errors_on_every_surface() {
465	        let fields: Vec<String> = (0..=crate::toon::MAX_FIELDS).map(|i| format!("f{i}")).collect();
466	        let field_refs: Vec<&str> = fields.iter().map(String::as_str).collect();
467	        let too_wide = AgentResponse::new("t").items(vec![], &field_refs);
468	        let long_hint = AgentResponse::new("t")
469	            .items(vec![vec![Value::from("x")]], &["a"])
470	            .truncation_hint("h".repeat(crate::toon::MAX_TRUNCATION_HINT_CHARS + 1));
471	        for (r, message) in [
472	            (too_wide, "fields length 1001 exceeds maximum of 1000"),
473	            (long_hint, "truncation_hint length 257 chars exceeds maximum of 256"),
474	        ] {
475	            assert!(r.is_error(), "{message}");
476	            let text = r.render(OutputFormat::Text);
477	            assert_eq!(text, format!("error: toon_validation_failed\nmessage: {message}"));
478	            assert!(r.render(OutputFormat::Json).contains("\"isError\":true"), "{message}");
479	            let result = r.to_call_tool_result();
480	            assert!(result.is_error, "{message}");
481	            assert_eq!(result.content[0].text, text);
482	            assert!(result.structured_content.contains("\"isError\":true"), "{message}");
483	        }
484	    }
