486	    #[test]
487	    fn is_error_agrees_with_the_rendered_flag_for_every_target() {
488	        use crate::kv::{KvItem, KvValue};
489	        let kv = |key: &str| KvItem { key: key.into(), value: KvValue::Int(1) };
490	        let cases = [
491	            AgentResponse::new("t"),
492	            AgentResponse::new("help"),
493	            AgentResponse::new("t").items(vec![vec![Value::Int(1)]], &["a"]),
494	            AgentResponse::new("t").items(vec![vec![Value::Int(1)]], &["a", "b"]),
495	            AgentResponse::new("t").kv_items(vec![]),
496	            AgentResponse::new("t").kv_items(vec![kv("a")]),
497	            AgentResponse::new("t").kv_items(vec![kv("a"), kv("a")]),
498	            AgentResponse::new("t").kv_items(vec![kv("a")]).as_error(),
499	        ];
500	        for r in cases {
501	            assert_eq!(r.is_error(), r.to_call_tool_result().is_error, "{r:?}");
502	        }
